'use client'

import * as React from 'react'
import NumberFlow, { NumberFlowGroup } from '@number-flow/react'
import {
  IconPlayerPause,
  IconPlayerPlay,
  IconPlus,
  IconRotateClockwise,
} from '@tabler/icons-react'
import { AnimatePresence, MotionConfig, motion } from 'motion/react'
import { cn } from '@/lib/utils'

export interface FluidCountdownProps {
  /** Starting time in seconds. @default 33 */
  duration?: number
  /** Begin counting down immediately on mount. @default true */
  autoStart?: boolean
  /** Restart automatically when the timer reaches zero. @default false */
  loop?: boolean
  /** Render the play/pause, reset, and quick-add controls. @default true */
  showControls?: boolean
  /** Show an elapsed progress bar below the numerals. @default true */
  showProgress?: boolean
  /** Uppercase caption shown in the header pill. @default "Countdown" */
  label?: string
  /** Accent color used for active elements and primary controls. @default "#6366f1" */
  accentColor?: string
  /** Enable keyboard shortcuts (Space = toggle, R = reset). @default true */
  keyboardControls?: boolean
  /** Called once the timer reaches zero. */
  onComplete?: () => void
  /** Called on each second tick with the remaining time in seconds. */
  onTick?: (timeLeft: number) => void
  /** Additional classes for the container. */
  className?: string
  /** Additional classes applied directly to the numeric digits. */
  digitClassName?: string
}

export function FluidCountdown({
  duration = 33,
  autoStart = true,
  loop = false,
  showControls = true,
  showProgress = true,
  label = 'Countdown',
  accentColor = '#6366f1',
  keyboardControls = true,
  onComplete,
  onTick,
  className,
  digitClassName,
}: FluidCountdownProps) {
  const [totalDuration, setTotalDuration] = React.useState(duration)
  const [timeLeft, setTimeLeft] = React.useState(duration)
  const [running, setRunning] = React.useState(autoStart)
  const [mounted, setMounted] = React.useState(false)

  React.useEffect(() => {
    setMounted(true)
  }, [])

  // Sync state if duration prop changes externally
  React.useEffect(() => {
    setTotalDuration(duration)
    setTimeLeft(duration)
  }, [duration])

  // Countdown timer loop
  React.useEffect(() => {
    if (!running) return

    const id = setInterval(() => {
      setTimeLeft((prev) => {
        const next = prev - 1
        if (next <= 0) {
          if (loop) {
            return totalDuration
          }
          setRunning(false)
          return 0
        }
        onTick?.(next)
        return next
      })
    }, 1000)

    return () => clearInterval(id)
  }, [running, loop, totalDuration, onTick])

  // Completion callback
  React.useEffect(() => {
    if (timeLeft === 0 && !loop) {
      onComplete?.()
    }
  }, [timeLeft, loop, onComplete])

  const toggle = React.useCallback(() => {
    if (timeLeft === 0) {
      setTimeLeft(totalDuration)
    }
    setRunning((prev) => !prev)
  }, [timeLeft, totalDuration])

  const reset = React.useCallback(() => {
    setRunning(false)
    setTimeLeft(totalDuration)
  }, [totalDuration])

  const addSeconds = React.useCallback((secs: number) => {
    setTotalDuration((prev) => prev + secs)
    setTimeLeft((prev) => prev + secs)
  }, [])

  // Keyboard controls
  React.useEffect(() => {
    if (!keyboardControls) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement
      ) {
        return
      }

      if (e.code === 'Space') {
        e.preventDefault()
        toggle()
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault()
        reset()
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [keyboardControls, toggle, reset])

  const minutes = Math.floor(timeLeft / 60)
  const seconds = timeLeft % 60
  const progress =
    totalDuration > 0
      ? Math.min(100, Math.max(0, ((totalDuration - timeLeft) / totalDuration) * 100))
      : 0

  return (
    <MotionConfig reducedMotion="user">
      <div
        role="timer"
        aria-live="polite"
        aria-label={`${label}: ${minutes} minutes and ${seconds} seconds remaining`}
        className={cn(
          '[container-type:inline-size] relative flex w-full max-w-xl flex-col items-center justify-center gap-6 rounded-3xl border border-border/50 bg-card/40 p-6 sm:p-8 backdrop-blur-xl select-none shadow-sm transition-all',
          className,
        )}
      >
        {/* Header Status Capsule */}
        <div className="flex items-center gap-2 rounded-full border border-border/60 bg-muted/60 px-3.5 py-1 text-xs font-medium text-foreground/80 shadow-xs">
          <span
            className={cn(
              'size-2 rounded-full transition-colors duration-300',
              running
                ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.7)] animate-pulse'
                : timeLeft === 0
                  ? 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.7)]'
                  : 'bg-muted-foreground/50',
            )}
          />
          <span className="text-[11px] font-semibold tracking-wider uppercase">
            {timeLeft === 0 ? 'Finished' : running ? 'Live' : 'Paused'}
          </span>
          {label && (
            <>
              <span className="text-muted-foreground/40">•</span>
              <span className="text-muted-foreground text-[11px]">{label}</span>
            </>
          )}
        </div>

        {/* Numerals display with container-inline fluid sizing */}
        <div
          className={cn(
            'flex items-baseline justify-center font-bold tracking-tight tabular-nums font-sans leading-none text-foreground drop-shadow-xs',
            'text-[clamp(3.25rem,18cqi,8rem)]',
            digitClassName,
          )}
        >
          {mounted ? (
            <NumberFlowGroup>
              <NumberFlow value={minutes} trend={-1} />
              <span className="px-[0.06em] opacity-40 font-light select-none">:</span>
              <NumberFlow
                value={seconds}
                trend={-1}
                format={{ minimumIntegerDigits: 2 }}
              />
            </NumberFlowGroup>
          ) : (
            <>
              <span>{minutes}</span>
              <span className="px-[0.06em] opacity-40 font-light">:</span>
              <span>{String(seconds).padStart(2, '0')}</span>
            </>
          )}
        </div>

        {/* Progress Bar */}
        {showProgress && (
          <div className="w-full max-w-xs sm:max-w-sm flex flex-col gap-1.5">
            <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted/70">
              <motion.div
                className="h-full rounded-full transition-all duration-300 ease-out"
                style={{
                  width: `${progress}%`,
                  backgroundColor: accentColor,
                }}
              />
            </div>
            <div className="flex justify-between text-[10px] font-medium text-muted-foreground tabular-nums">
              <span>{Math.round(progress)}%</span>
              <span>
                {Math.floor(totalDuration / 60)}:
                {String(totalDuration % 60).padStart(2, '0')}
              </span>
            </div>
          </div>
        )}

        {/* Space UI Control Bar */}
        {showControls && (
          <div className="flex items-center gap-3 pt-1">
            {/* Quick +1 Min Button */}
            <button
              type="button"
              onClick={() => addSeconds(60)}
              aria-label="Add 1 minute"
              className="group flex h-10 items-center gap-1 rounded-2xl border border-border/60 bg-muted/70 px-3.5 text-xs font-semibold text-foreground/80 shadow-xs transition-all hover:bg-muted hover:text-foreground hover:scale-105 active:scale-95 cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <IconPlus className="size-3.5 transition-transform group-hover:rotate-90" />
              <span>1m</span>
            </button>

            {/* Primary Play / Pause Button with morph and glow */}
            <button
              type="button"
              onClick={toggle}
              aria-label={running ? 'Pause timer' : 'Start timer'}
              className="relative flex size-12 items-center justify-center rounded-2xl text-white shadow-lg transition-all hover:scale-108 active:scale-92 cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring"
              style={{
                backgroundColor: accentColor,
                boxShadow: `0 8px 24px -4px ${accentColor}66`,
              }}
            >
              <AnimatePresence mode="wait" initial={false}>
                <motion.span
                  key={running ? 'pause' : 'play'}
                  initial={{ opacity: 0, scale: 0.6, rotate: -20 }}
                  animate={{ opacity: 1, scale: 1, rotate: 0 }}
                  exit={{ opacity: 0, scale: 0.6, rotate: 20 }}
                  transition={{ duration: 0.15 }}
                >
                  {running ? (
                    <IconPlayerPause className="size-5 fill-current" />
                  ) : (
                    <IconPlayerPlay className="size-5 fill-current translate-x-0.5" />
                  )}
                </motion.span>
              </AnimatePresence>
            </button>

            {/* Reset Button */}
            <button
              type="button"
              onClick={reset}
              aria-label="Reset timer"
              className="flex size-10 items-center justify-center rounded-2xl border border-border/60 bg-muted/70 text-muted-foreground shadow-xs transition-all hover:bg-muted hover:text-foreground hover:scale-105 active:scale-95 cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <IconRotateClockwise className="size-4.5 transition-transform hover:-rotate-45" />
            </button>
          </div>
        )}
      </div>
    </MotionConfig>
  )
}

export { FluidCountdown as CountdownTimer }
export type { FluidCountdownProps as CountdownTimerProps }
